  "karte.fuss": "{raum}: треки Suno сгруппированы в виде звёзд. Каждая звезда — трек. {naehe}: карта рассчитана методом {verfahren} {woher}, локально на этом компьютере. {fehlen}{gruppen}Использованы данные собственного анализа. Данные на {stand}.",
