  "morgen.durch_fehler": "Готово. С ошибкой завершён {n} этап. Откройте «Подробности» и повторите запуск.|Готово. С ошибкой завершены {n} этапа. Откройте «Подробности» и повторите запуск.|Готово. С ошибкой завершено {n} этапов. Откройте «Подробности» и повторите запуск.",
