  "morgen.kreuz.ernte": "Учесть данные закладки",
  "morgen.kreuz.ernte.text": "Профиль, приватные треки, подписчики и история счётчиков — учитываются при сборке каталога.",
  "morgen.kreuz.kommentare": "Сохранить комментарии",
