  "morgen.kreuz.medien": "Загрузить медиа",
  "morgen.kreuz.medien.text": "Недостающие MP3, обложки, видео и уже созданные в Suno WAV. Требует интернета и места на диске.",
  "morgen.kreuz.nachbarn": "Обновить окружение",
  "morgen.kreuz.nachbarn.text": "Публичная статистика профилей и индекс Хирша пользователей, добавившихся в окружение со вчерашнего дня. Обычно занимает несколько секунд. Полное обновление доступно по кнопке на панели окружения.",
  "morgen.kreuz.katalog": "Собрать каталог",
