  "profil.nb.min": "не менее ",
  "profil.nb.unten": " Для {n} значения достигнут лимит страниц. Знак ≥ означает нижнюю границу; порядок лидеров ещё не окончательный.| Для {n} значений достигнут лимит страниц. Знак ≥ означает нижнюю границу; порядок лидеров ещё не окончательный.| Для {n} значений достигнут лимит страниц. Знак ≥ означает нижнюю границу; порядок лидеров ещё не окончательный.",
  "profil.nb.kopf3": "Сначала вопрос, потом подсчёт: <b>Что считать «охватом»?</b> Возможны три разных ответа. Каждый объясняется только <b>действиями</b> — тем, что человек делает до получения отклика. Другие результаты не объясняют его: много лайков вместе с большим числом подписчиков — один и тот же эффект, посчитанный дважды.",
