  "profil.nb.zu_wenige": "Недостаточно данных для расчёта. Загрузите больше профилей кнопкой «Загрузить новые профили» на панели окружения или выберите другой показатель.",
  "profil.nb.anteil": "<b>{name}</b> — {was}. Действия вместе объясняют <b>{gesamt}%</b> общего разброса; наибольший отдельный вклад у «{stark}»: {starkp}%. Число людей в расчёте: {n}; все величины логарифмированы.<br><span class=\"leise\">Вклад усреднён по <b>всем</b> порядкам включения величин в модель (Lindeman, Merenda и Gold; та же идея, что у распределения Shapley). Иначе общий вклад достался бы первой включённой величине. <b>Вклад не означает причинность:</b> человек с множеством подписчиков может чаще подписываться в ответ; один срез данных не показывает направление связи.</span>",
