  "profil.nb.info.kurz_h": "Краткое объяснение",
  "profil.nb.info.kurz": "Ваше сообщество — <b>не случайная выборка</b>. Это люди, которые нашли вас, а находят вас прежде всего заметные пользователи.",
  "profil.nb.info.p1": "Это известный эффект — <i>парадокс дружбы</i>: <b>у ваших друзей в среднем больше друзей, чем у вас.</b> Он проявляется почти всегда и почти у всех. Это не оценка, а следствие устройства окружения: подписанный на три тысячи человек попадает в три тысячи окружений, а подписанный на тридцать — в тридцать. Поэтому пользователи с большим числом подписок представлены в вашем списке в сто раз чаще.",
  "profil.nb.info.p2": "Scott Feld описал это в 1991 году; Eom и Jo в 2014 году показали, что эффект распространяется почти на любой связанный показатель, а не только на число связей. У учёных — на цитирования, здесь — на прослушивания и лайки.",
  "profil.nb.info.messbar_h": "Что видно в ваших данных",
  "profil.nb.info.messbar": "Чем выше среднее относительно медианы, тем сильнее несколько крупных пользователей влияют на показатели и тем сильнее искажение из-за отбора:",
  "profil.nb.info.th.mitte": "Медиана",
  "profil.nb.info.th.mittel": "Среднее",
  "profil.nb.info.th.verhaeltnis": "Отношение",
  "profil.nb.info.th.oben": "доля топ-10%",
  "profil.nb.info.hirsch_h": "Почему индекс Хирша — самый честный показатель",
  "profil.nb.info.hirsch": "Это наименее искажённая величина. В этом её сила: один успешный трек не повышает индекс — нужен успех сразу многих треков. Поэтому эффект отбора влияет на него слабее всего. Рейтинг по прослушиваниям сильно искажён, по индексу Хирша — меньше всего.",
  "profil.nb.info.bilder_h": "Что это значит для графиков",
  "profil.nb.info.bilder_p1": "<b>«Я в нижней трети своего сообщества» верно почти для каждого</b>, даже для тех, кто намного выше среднего среди всех пользователей. Вы систематически сравниваете себя с самыми заметными.",
  "profil.nb.info.bilder_p2": "Для точного измерения нужна случайная выборка всех пользователей Suno. Этот способ её не даёт: человек находится, только если где-то проявился, и тот же эффект возникает снова.",
  "profil.nb.info.fuss": "Показатели выше рассчитаны по участникам окружения, которые сами создают музыку. Их число: {n}. Данные описывают ваше окружение, а не весь Suno.",
  "profil.nb.info.fuss_unten": " При расчёте индексов Хирша ({n}) достигнут лимит страниц: это нижние границы, занижающие медиану и среднее.",
  "profil.befund.monat": "Треков по месяцам",
  "profil.befund.monat.hinweis": "Сверху: первое появление модели.",
  "profil.befund.herzen_monat": "Лайки на трек по месяцу создания (медиана)",
  "profil.befund.herzen_monat.hinweis": "У старых треков было больше времени собрать отклик. Это картина данных, а не оценка качества.",
  "profil.befund.herzen_monat.tipp": "{k} (треков: {n})",
