  "profil.kurios.laut.fuss": "Лайки учтены по полным спискам пользователей, поставивших лайк вашим трекам; комментарии и ответы — в пределах истории уведомлений (четыре недели).",
  "profil.kurios.laut.keine": "Нет данных сообщества. Нажмите закладку «KlangTresor morgens» на Suno (инструкция в «Обновить библиотеку»), и они появятся здесь.",
