  "profil.kurios.ton.fuss": "{liste}; всего измеренных треков: {n}. Разных тональностей: {arten}.",
  "export.titel": "KlangTresor на внешнем диске",
  "export.erklaerung": "Полная неизменяемая копия библиотеки записывается на переносной диск. Подключите его к нужному устройству и запустите стартовый скрипт: браузер откроет KlangTresor со всеми треками. Можно слушать; данные не загружаются и не сохраняются. Также создаётся папка <code>Musik/</code> с MP3, названными по трекам, и встроенными обложками — для телевизора, автомагнитолы и VLC. Повторный экспорт на тот же диск обновляет изменения.",
  "export.wohin": "Куда",
