  "studio.fx.tempo": "Темп",
  "studio.fx.tempo.skala": "вдвое медленнее · обычный · вдвое быстрее",
  "studio.fx.spass": "Кнопка для удовольствия",
  "studio.fx.megabass.was": "Дополнительное усиление баса. Отключите его, чтобы вернуться к прежнему звучанию.",
  "studio.fx.tempo_hinweis": "Темп ≠ 100% также влияет на индикаторы и синхронизацию караоке.",
  "studio.fx.lampen": "Индикатор горит, только когда эффект действительно работает. Исключение — CLIP: он предупреждает о предельном уровне на выходе, где складываются EQ, ширина, реверберация и эхо. Стереоширина и темп — <b>состояния, а не количество эффекта</b>: ползунки без заливки, исходное положение в центре. Темп не запоминается: забытые 150% сбивали бы с толку. Временные режимы (темп, соло, MEGA BASS, отключённый блок обработки, A/B) после закрытия окна продолжают подсвечивать кнопку EQ в плеере.",
  "mess.wozu.titel": "Зачем проверять помещение?",
