  "studio.eq.wirkt": "Звуковая студия — эквалайзер · действует: {was}",
  "studio.byp.eq": "Включить или отключить EQ (полосный или параметрический режим). Воспроизведение продолжается, настройки сохраняются.",
  "studio.byp.komp": "Включить или отключить ступень компрессии (компрессор / Градационный компрессор). Звук продолжает играть, кривая сохраняется.",
  "studio.byp.fx": "Включить или отключить эффекты (ширина, реверберация, эхо, темп). Звук продолжает играть, настройки сохраняются.",
  "studio.byp.komp.knopf": "Компрессор",
  "studio.byp.fx.knopf": "Эффекты",
  "studio.kette": "Звуковая цепь: как соединены блоки обработки и где измеряются сигнал и результат обработки",
  "studio.reg.eq": "Эквалайзер",
  "studio.reg.ghetto": "Бумбокс",
  "studio.reg.ghetto.titel": "Бумбокс старого образца: отдельный переключатель для тонкомпенсации, баса, верхов и ночного режима",
  "studio.reg.mess": "Проверка помещения",
  "studio.eqmodus": "Эквалайзер: восемь фиксированных полос. Параметрический EQ: те же фильтры со свободной настройкой. У шести колоколообразных фильтров регулируются частота, усиление и добротность Q, определяющая ширину полосы. Два крайних фильтра усиливают или ослабляют все частоты ниже или выше заданной границы. Одновременно работает только один режим.",
  "studio.eq.glockenstuhl": "Параметрический EQ",
  "studio.ref.knopf": "Взять текущий трек за эталон",
  "studio.ref.titel": "Запомнить текущий трек как образец звучания. Начальная настройка «Как эталонный трек» подгонит частотный профиль других треков под него.",
  "studio.ref.weg": "Убрать эталон",
  "studio.deckel": "Без перегрузки",
  "studio.deckel.titel": "Усиление во всех полосах не превышает серую границу, рассчитанную для трека, — при включении, перетаскивании и выборе начальных настроек. MEGA BASS добавляется поверх и этой границей не ограничивается. О перегрузке предупреждает индикатор CLIP.",
  "studio.shift": "Общий сдвиг: поднять или опустить все полосы вместе",
  "studio.invers": "Инвертировать",
  "studio.invers.titel": "Инверсия: звучат все полосы, кроме выбранных",
  "studio.stapel.titel": "Отдельные фильтры: кривая каждого колоколообразного фильтра показана отдельно. Наложение кривых фильтров: вклады складываются, усиление направлено вверх, ослабление — вниз; внешний контур показывает сумму.",
  "studio.stapel.einzeln": "Отдельные фильтры",
  "studio.stapel.stapel": "Наложение кривых фильтров",
  "studio.mittel": "Усреднение графика",
  "studio.mittel.titel": "Как быстро серая область спектра реагирует на изменения в треке: скользящее среднее за заданный интервал. При коротком интервале график меняется быстро и резко, при длинном — становится плавнее и реагирует с задержкой.",
  "studio.ausgang.titel": "Что сейчас звучит из динамиков после EQ, компрессора и эффектов",
  "studio.clip.titel": "Звук достигает предельного уровня и обрезается. Уменьшите обработку: EQ, ширина, реверберация и эхо складываются.",
  "studio.breite.titel": "Стереоширина: 0% — моно (левый и правый каналы одинаковы), 100% — как в записи, 200% — разница между каналами удвоена",
  "studio.breite.vor": "до компрессора",
  "studio.breite.vor.titel": "Два подхода. Выключено: ширина после компрессора — изменение звучания после регулировки уровня, но и после лимитера, который уже не защитит от перегрузки. Включено: ширина до компрессора — он видит готовую стереокартину и удерживает даже удвоенную боковую составляющую в пределах шкалы, как при мастеринге. Реверберация и эхо в обоих случаях получают сигнал после компрессора.",
  "studio.hall.titel": "Реверберация большого помещения с затуханием 2 с. Эквалайзер не может УБРАТЬ реверберацию.",
  "studio.echo.titel": "Эхо бумбокса: задержанная копия с обратной связью (дилей)",
  "studio.echozeit.titel": "Интервал между повторами в миллисекундах",
