  "studio.solo": "Соло: слушать только эту полосу. Повторный клик возвращает полный микс.",
  "studio.freq": "Центральная частота,  Hz",
  "studio.q": "Добротность Q: высокое значение — узкая полоса, низкое — широкая",
  "studio.titel_eq": "Трек: {teile}",
  "studio.titel_eq_aus": "Трек: {teile} выкл.",
  "mess.dokument": "Измерить акустику помещения — отчёт",
  "mess.dokument.titel": "Полный цикл измерений в одном документе: проверка тишины и задержки (звуковой сигнал), три вида шума и два свипа по два раза, два ступенчатых подъёма громкости, рекомендации. Все диаграммы сохраняются; в конце доступен экспорт.",
  "mess.wirkung": "Измерить действие Звуковой студии",
  "mess.wirkung.titel": "Прежний пошаговый режим на панели: измеряет реальное действие эквалайзера в точке прослушивания (эталон, настройки, серии уровней).",
  "mess.signal": "Измерительный сигнал. Свип — тон, плавно поднимающийся от низких частот к высоким, — обычный сигнал для проверки акустики помещений. Здесь пока оценивается только уровень сигнала на каждой частоте в точке измерения; прямой звук ещё не отделяется от реверберации.",
  "mess.signal.sweep": "Свип · 20 Hz – 20 kHz",
  "mess.signal.rosa": "Розовый шум",
  "mess.signal.weiss": "Белый шум",
  "mess.signal.band": "По тону на полосу эквалайзера — в центре каждой из восьми полос",
  "mess.mikro": "Устройство записи. Виртуальные устройства не подходят: они не слышат помещение, а передают звук внутри компьютера.",
  "mess.abhoeren": "Послушать помещение",
  "mess.abhoeren.titel": "Без воспроизведения: непрерывно показывает уровень шума в помещении и мешающие частоты. Помогает выбрать тихое место для микрофона.",
  "mess.rampe": "Ступенчато поднять уровень",
  "mess.rampe.titel": "Меняет громкость по ступеням с измерением на каждой. Показывает, растёт ли всё равномерно или с какого-то уровня рост ограничивается.",
  "mess.abbrechen": "Отменить",
  "mess.abbrechen.titel": "Остановить текущее измерение. Посторонний шум в помещении всё равно его испортит.",
  "mess.leeren": "Очистить серию",
  "mess.leeren.titel": "Удалить собранные измерения. Нейтральный эталон сохраняется.",
  "mess.neutral": "1 · Нейтрально",
  "mess.neutral.titel": "Первое измерение с обходом Звуковой студии. Без обработки видна только цепь «динамик — помещение — микрофон».",
  "mess.mit": "2 · С обработкой",
  "mess.mit.titel": "Второе измерение с текущей настройкой.",
  "mess.hg": "Показать или скрыть пояснения",
  "komp.modus": "Компрессор: классическая кривая перегиба (порог, степень сжатия, компенсация, лимитер). Градационный компрессор: тихая и громкая точки, как чёрная и белая в графике; гамма или сигмоида одним регулятором — графический редактор для звука. Активен один режим, настройки другого сохраняются.",
  "komp.kompressor": "Компрессор",
  "komp.gradation": "Градационный компрессор",
  "komp.aus": "Выкл.",
  "komp.aus.titel": "Без кривой — линейно, без изменений",
  "komp.gamma": "Гамма",
  "komp.gamma.titel": "Гамма по оси dB между тихой и громкой точками: γ < 1 поднимает тихое и сжимает громкое, как осветление теней. Внизу кривая круче, затухания быстрее уходят в тишину. При γ > 1 — наоборот.",
  "komp.sig": "Сигмоида",
  "komp.sig.titel": "Сигмоида: + повышает контраст средних уровней и сглаживает края (сверху — как мягкий лимитер); − сжимает средние уровни и делает края круче, усиливая контраст тихого и громкого.",
  "komp.staerke": "Сила",
  "komp.staerke.titel": "Сила действия кривой: гамма ¼ … 4, сигмоида −10 … +10",
  "komp.leise_laut": "Тихо / громко",
  "komp.leise_laut.titel": "Тихая точка (чёрная) · громкая точка (белая)",
  "komp.limiter": "Лимитер",
  "komp.limiter.titel": "Лимитер: порог −3 dB, 20:1. Удерживает пики, а не средний уровень: пики ловит мгновенно, громкость — с атакой 3 мс. Смотрит на один блок вперёд и в крайнем случае жёстко обрезает сигнал на вершине кривой. Это защита, а не окраска звука.",
  "komp.gr.titel": "Изменение уровня: сколько компрессор сейчас убирает (−) или добавляет (+)",
  "komp.schwelle": "Порог",
  "komp.schwelle.titel": "Порог: входной уровень, с которого кривая изгибается. Ниже него сигнал не меняется.",
  "komp.verhaeltnis": "Степень сжатия",
  "komp.verhaeltnis.titel": "Степень сжатия: наклон выше порога. При 4:1 рост входа на 4 dB даёт рост выхода на 1 dB.",
  "komp.attack": "Атака",
  "komp.attack.titel": "Атака: как быстро компрессор срабатывает при росте громкости, подобно автоэкспозиции при усилении света. В режиме лимитера: пики мгновенно, громкость — с атакой 3 мс.",
  "komp.release": "Восстановление",
  "komp.release.titel": "Восстановление: как быстро компрессор отпускает сигнал при снижении громкости, подобно автоэкспозиции при переходе в темноту",
  "komp.aufholen": "Компенсация",
  "komp.aufholen.titel": "Компенсация: возвращает громкость, убранную компрессором. Одинаково поднимает весь сигнал до предельных 0 dB; всё выше обрезается.",
  "komp.diagonale": "Сбросить кривую",
  "komp.diagonale.titel": "Вернуть активный инструмент к диагонали. Настройки другого сохраняются.",
  "kachel.video_eigen": "назначенная вами анимированная обложка",
