  "sa.chart.karten": "Основные общие параметры для оценки трека.",
  "sa.chart.befunde": "Сверху — разделы из промпта с текстом песни. Ниже — огибающая громкости, доли (BPM) и результаты проверки: отмечены участки возможного взаимного гашения стереосигналов и превышения целевого уровня. Это общий ориентир перед подробным просмотром отдельных измерений. Указатель воспроизведения (белая вертикальная линия) проходит по всем временным дорожкам, связывая каждое наблюдение с конкретным местом песни.",
