  "sa.tip.plays": "Общее число прослушиваний на Suno.",
  "sa.tip.likes": "Число лайков.",
  "sa.tip.comments": "Число комментариев.",
  "sa.tip.ratio": "Прослушивания на один лайк. Чем меньше значение, тем чаще слушатели ставят лайки.",
  "sa.tip.age": "Время с публикации песни.",
  "sa.tip.ppd": "Среднее число прослушиваний в день с публикации.",
  "sa.tip.model": "Версия модели Suno, создавшей песню.",
  "sa.tip.dur": "Полная длительность песни.",
  "sa.tip.loud": "Средний уровень всего трека в децибелах ниже предела (0 dB). Это физическое измерение, а не воспринимаемая громкость, на которую ориентируются стриминговые сервисы. Она показана в «Насколько громко в целом?». Обычно от −18 до −10 dB.",
  "sa.tip.dyn": "Превышение самых высоких пиков над средним уровнем. Большое — живые удары, малое — плотный сжатый звук. Обычно 6–16 dB.",
  "sa.tip.key": "Тоника определяется по басу на сильных долях по разметке Suno: там почти всегда звучит основной тон аккорда. Мажор или минор — по встречаемости терции в мелодических партиях. Если терции нет (обычно в пауэр-аккордах), показана только тоника.",
  "sa.tip.grenz": "До какой частоты простирается высокочастотный диапазон и насколько резок спад. Указана частота, выше которой уровень стабильно примерно на 30 дБ ниже, чем в среднем диапазоне (1–8 кГц). Дополнительное слово описывает спад: «резкий» — от 20 dB на кГц; такую границу может оставлять формат MP3 или сама модель. «Мягкий» — естественное плавное затухание. При измерении пяти WAV-файлов Suno 26 августа 2026 года уровень от 17 до 21 кГц снижался на 8,5–19,6 dB, то есть спад во всех случаях был МЯГКИМ. У MP3 с битрейтом 192 кбит/с спад здесь превышает 40 dB в пределах одного килогерца. Измерение по MP3 показало бы частотную границу этого формата, а не модели, поэтому с 26 августа 2026 года расчёт выполняется только по WAV.",
  "sa.tip.stereo": "Стереоширина: насколько различаются левый и правый каналы. Обычно 15–70%.",
  "sa.tip.entropy": "Равномерность распределения энергии по частотам (спектральная энтропия). Низкое значение — отчётливые тоны и чистое звучание, высокое — шумоподобный, плотный звук.",
  "sa.tip.symmetry": "Как энергия меняется на протяжении песни. Кривая громкости оценивается по трём частям: становится громче ↑, тише ↓, сначала громче, затем тише ∧ или остаётся ровной ─.",
  "sa.tip.flux": "<b>Изменение тембра (спектральный поток) — 8 полос</b><br>По горизонтали: время · 8 строк = 8 частотных полос (басы снизу, верха сверху)<br>Яркость — сила изменения полосы от мгновения к мгновению; у каждой полосы своя шкала.<br><br>Вспышка в басу — бас-барабан. В верхах — тарелки. Широкая вспышка во многих полосах — резкое вступление синтезатора. Всё тёмное — неизменная звуковая подложка. Мерцающая середина — мелодия с быстрыми нотами.",
  "sa.tip.spectro": "<b>Спектрограмма (время × частота)</b><br>По горизонтали: время · по вертикали: частота (20 Hz–22 kHz) с нотным станом<br>Чёрный — нет сигнала. Белый — сильный сигнал. <span style=\"color:#f97306\">Оранжевый</span> — самые громкие десять процентов в этом месте.<br><br>Светлые горизонтали — протяжные тоны. Вертикальные штрихи — удары, барабаны. Оранжевые области — преобладающие частоты. Каждая точка измеряется относительно окружения, чтобы тихие фрагменты тоже были видны.",
  "sa.tip.stereospectro": "<b>Стереоспектрограмма — панорама по частотам</b><br>X: время · Y: частота · цвет: направление панорамы<br><span style=\"color:#ff6600\">■ Оранжевый</span> — преобладает левый канал. <span style=\"color:#1472eb\">■ Синий</span> — правый. Серый — центр. Яркость — амплитуда.<br><br>Почти всегда серый бас — аккуратный микс. Часто оранжевые/синие верха — широко разведённая реверберация. Частота одного цвета — инструмент у края панорамы.",
  "sa.tip.freq": "<b>Частотный спектр в реальном времени</b><br>По горизонтали: частота (20 Hz–20 kHz) · по вертикали: уровень<br>Показывает звучащие сейчас частоты. Басы слева, середина в центре, верха справа.<br><br>Пики — преобладающие частоты. Ровная заливка — плотный звук. Меняется вместе с музыкой.",
