  "groupie.mass.beides.was": "Площадь пузырька пропорциональна сумме лайков и комментариев пользователя к вашим трекам.",
  "groupie.mass.herzen": "Лайки",
  "groupie.mass.herzen.text": "лайки: {n}",
  "groupie.mass.herzen.was": "Площадь пузырька пропорциональна числу лайков пользователя к вашим трекам. Те, кто только комментирует, скрыты.",
  "groupie.mass.kommentare": "Комментарии",
  "groupie.mass.kommentare.text": "комментариев: {n}",
  "groupie.mass.kommentare.was": "Площадь пузырька пропорциональна числу комментариев и ответов пользователя под вашими треками. Те, кто только ставит лайки, скрыты.",
  "groupie.mass.zeichen": "Длина комментариев",
  "groupie.mass.zeichen.text": "знаков: {n}",
  "groupie.mass.zeichen.was": "Площадь пузырька пропорциональна суммарной длине всех комментариев и ответов пользователя на вашей странице (в знаках). Те, кто только ставит лайки, скрыты.",
  "groupie.mass.aktuell": "Недавние",
  "groupie.mass.aktuell.text": "{n} (с весами)",
  "groupie.mass.aktuell.was": "Лайки и комментарии с учётом давности: сегодняшние учитываются полностью, месячной давности — наполовину, двухмесячной — на четверть. Те, кто не проявлял активности около четырёх месяцев, скрыты.",
  "groupie.mass.titel": "Треки",
  "groupie.mass.titel.text": "треков: {n}",
  "groupie.mass.titel.was": "Площадь пузырька пропорциональна числу ваших треков, которым пользователь поставил лайк или под которыми оставил комментарий.",
  "groupie.mass.treue": "Постоянство",
  "groupie.mass.treue.text": "дней: {n}",
  "groupie.mass.treue.was": "Площадь пузырька пропорциональна числу дней между первой и последней реакциями пользователя. Если пользователь проявил активность лишь однажды, учитывается один день.",
  "groupie.glied.art": "Вид реакции",
  "groupie.glied.art.was": "Группировка: только лайки, только комментарии или и то и другое.",
  "groupie.glied.beziehung": "Связь",
  "groupie.glied.beziehung.was": "Кто подписан на вас и на кого подписаны вы — по последнему списку подписчиков.",
  "groupie.glied.ankunft": "Первая реакция",
  "groupie.glied.ankunft.was": "Год первой реакции. У многих лайков из списков Suno нет временной отметки. Если пользователь оставлял только такие лайки, он попадает в группу «время неизвестно».",
  "groupie.glied.lebendig": "Активность",
  "groupie.glied.lebendig.was": "Была ли последняя реакция за последние четыре недели.",
  "groupie.glied.geschmack": "Вкус",
  "groupie.glied.geschmack.was": "Стилевая группа Звукового пространства, чьи треки человек предпочитал чаще всего с учётом числа треков в группе. Цвета как в Звуковом пространстве.",
  "groupie.areal.herzen": "только лайки",
