  "mess.dok.m.legende": " Сверху: кривая измерения с высоким разрешением, входной сигнал — пунктир, тишина — точки снизу. Внизу: разность — <b>сама кривая помещения</b>, с заливкой относительно нуля.",
  "mess.dok.n.abstand": "превышение над шумом {db} dB",
  "mess.dok.r.titel": "ПОДЪЁМ ГРОМКОСТИ · {name}",
  "mess.dok.r.text": "Уровень приложения начинается с <b>установленного измерительного ({p} %)</b>: ниже измерение было бы случайным. Затем растёт ступенями по 3 dB до 100 %. Сигнал «{name}» звучит по три секунды на каждой ступени. После ступени добавляется кривая; лестница снизу сопоставляет факт и ожидание. Подъём идёт до снижения баса, <b>подтверждённого следующей ступенью</b>. Тогда поведение динамика известно, а дальнейший рост покажет лишь лимитер. Если ограничения нет, подъём идёт до 100 %. Результат даётся как <b>рекомендация</b>.",
  "mess.dok.r.laut": "⚠ Последняя ступень — <b>максимальная громкость</b>. Будет громко.",
  "mess.dok.r.vorher": "Перед этим, как всегда, проверка тишины.",
  "mess.dok.r.start": "Начать подъём",
  "mess.dok.r.kulisse": "⚠ Фон изменился ({db} dB на {hz} Hz).",
  "mess.dok.r.trotzdem": "Всё равно начать",
  "mess.dok.r.oben": "Измерительный уровень уже {p} %. Запаса для подъёма нет. Пропущено.",
  "mess.dok.weiter": "Далее",
  "mess.dok.r.stufe": "Ступень <b>{p} %</b> — {name}, 3 с…",
  "mess.dok.r.fehl": "Ошибка ступени {p} %: {was}",
  "mess.dok.r.neu": "Повторить подъём",
  "mess.dok.n.stufe": "ступень {p} %: {was}",
  "mess.dok.r.je_laut": "Кривые помещения по уровням громкости. Если совпадают, система остаётся линейной:",
  "mess.dok.r.grenze": "Поведение определено: начиная с {p} %, бас отстаёт от середины более чем на 4 dB",
