  "mess.dok.z.guete_fein": " <span class=\"dokfein\">(верно выше примерно 100–200 Hz; ниже в жилых комнатах важны отдельные стоячие волны, а для реверберации ещё не реализован один расчёт)</span>",
  "mess.dok.z.fehlt": "<b>Чего пока не хватает по сравнению с современной практикой</b> (исследование от 28 августа): расчёта, превращающего запись свипа в отклик помещения на одиночный импульс. Он дал бы время реверберации, ясность, искажения по гармоникам и отражения с задержками из тех же записей, без нового сигнала.",
  "mess.dok.z.alle": "<b>Все кривые помещения</b> показаны полностью в <b>сопоставимом диапазоне {band}</b>: там не менее 60 % подходящих измерений превышают свой фон на 20 dB. Вне его кривые бледные — выводов там нет:",
