  "mess.dok.z.eq_oeffnen": "Открыть эквалайзер",
  "mess.dok.z.eq_nichts": "<b>Ослабление EQ:</b> в согласованной кривой ни одна полоса не выше соседних более чем на 3 dB. Коррекция не нужна.",
  "mess.dok.z.komp": "<b>Компрессор</b> — два аспекта:",
  "mess.dok.z.komp_kette": "Что уже сжимает цепь",
  "mess.dok.z.komp_hoer": "Что нужно для слышимости",
