  "mess.dok.z.komp_selbst": "До предельного уровня цепь убирает {db} dB — сжимает сама. Рекомендация: ослабьте компрессию студии (степень ближе к 1:1), иначе сжатие будет двойным.",
  "mess.dok.z.komp_ohne_rampe": "Без подъёма уровня нельзя оценить компрессию в цепи.",
