  "mess.geleert": "Серия очищена. Нейтральное эталонное измерение сохранено.",
  "mess.reihe.start": "Сейчас нужна тишина. Измерения свипом, примерно по 20 секунд. Громкость растёт ступенями по четыре децибела от {von} % максимум до {bis} %. Начинается тихо и останавливается, как только динамик сдерживает бас, поэтому громко станет лишь при необходимости. Всё остальное неизменно: сигнал, длительность, положение.",
