  "mess.plan.gelesen": " — прочитано.",
  "mess.plan.r.nichts": "С микрофона не поступил сигнал. Проверьте выбранное выше устройство.",
  "mess.plan.r.wert": "Уровень в помещении: <b>{db} dB</b>",
  "mess.plan.r.tiefst": ", минимум составил {db} dB",
  "mess.plan.r.ruhig": "Достаточно тихо, чтобы измерять негромко.",
  "mess.plan.r.brauchbar": "Пригодно. Измерять нужно чуть громче.",
  "mess.plan.r.laut": "Довольно шумно. Если можно отключить источник, сделайте это сейчас: один вентилятор компьютера легко даёт 10 dB, то есть десятикратную мощность. Отключите, измерьте снова — здесь появится сравнение.",
  "mess.plan.r.gleich": " С прошлого измерения ничего не изменилось.",
  "mess.plan.r.weniger": " Это <b>на {db} dB меньше</b>, чем прежде. Старая кривая показана жёлтым под новой: видно, какие полосы стали тише.",
  "mess.plan.r.mehr": " Это на {db} dB <b>больше</b>, чем прежде.",
  "mess.plan.r.aufnahmen": "<br><br>Усреднено за {s} с. Число снимков: <b>{n}</b>",
  "mess.plan.r.zappelt": "; колебания ещё {db} dB",
  "mess.plan.r.steht": " — картина стабилизировалась.",
  "mess.plan.r.schwankt": ". Полностью не стабилизировалось: значит, колеблется само помещение.",
  "mess.plan.n.nichts": "Сигнал не дошёл до микрофона. Проверьте громкость и устройство вывода, затем повторите.",
  "mess.plan.n.steht": "Эталон измерен, превышение над шумом <b>{db} dB</b>",
  "mess.plan.n.wenig": " — слишком мало. Поднимите громкость и повторите.",
  "mess.plan.n.traegt": ", этого достаточно.",
  "mess.plan.v.fehlt": "Нет эталонного измерения. Вернитесь на шаг назад.",
  "mess.plan.v.name": "Свип вместо шума",
  "mess.plan.nichts_wdh": "Сигнал не дошёл до микрофона. Повторите измерение.",
