  "ec.zone.zusaetzlich": "Также выбраны, но отсутствуют: {namen}. Выбор сохранится в рецепте и сработает на изображении с этими зонами.",
  "ec.quelle.vor.eine_schnuppe": "одна падающая звезда за клип",
