  "ec.zone.besch.effektraum": "пустое пространство спереди: дымка и частицы перед всем изображённым",
  "ec.wahl.tiefeVerdeckung.zone": "как в прежнем рецепте: мягкая маска зоны",
  "ec.text.stufe_szene": "Находится в сцене <b>под</b> эффектами ({namen}) и движется с камерой. Перетащите в конец цепи, чтобы текст снова оказался у объектива поверх всего.",
  "ec.stufe.szene.titel": "Сцена — эффект нарисован в диораме и движется с ней: при приближении камеры он увеличивается.",
  "ec.stufe.kamera.titel": "Камера — управление кадрированием: перемещение, масштаб, наклон, резкость.",
  "ec.stufe.film.titel": "Плёнка — эффект закреплён на камере: при зуме собственное зерно плёнки не увеличивается.",
  "ec.stufe.szene": "Сцена",
