  "ec.stufe.hinweis": "Порядок отрисовки фиксирован: сначала сцена, затем камера, в конце плёнка. Здесь порядок такой: {namen}. Перестановка карточек разных этапов не влияет на результат; важен порядок эффектов внутри одного этапа.",
