  "ec.karte.kein_medium": "В цепи <b>нет среды</b>. Без неё видно только то, <i>на что</i> попал луч, а не сам луч. <b>Кинодымка</b> делает его видимым, принимая свет в любом месте цепи.",
  "ec.karte.keine_leuchte": "В цепи нет света. Без него дымка лишь снижает контраст дали. Её проявят Прожектор, Лазер, Световые лучи, Огонь, Пламя, Каустика, светящиеся частицы или Стробоскоп.",
