  "ec.teilchen.ausdehnung_y": "Протяжённость Y",
  "ec.teilchen.kanone.punkt": "Пушка выпускает частицы из одной точки, даже если источник не выбран. Положение этой точки задаётся здесь. Если выбрать линию или круг, частицы будут вылетать из нескольких точек.",
  "ec.teilchen.schnuppe.quelle": "Падающая звезда всегда вылетает из одной точки. Без выбранного источника она появляется за пределами кадра и пролетает через него. Если источник задан, он определяет место её появления.",
  "ec.teilchen.schar.quelle": "Стая кружит вокруг движущегося центра. Если выбрать источник, центр закрепится в указанном месте: стая продолжит кружить вокруг него, но перестанет перемещаться по кадру.",
  "ec.teilchen.ueberall": "Частицы появляются по всему кадру и свободно перемещаются. Чтобы настроить напор, угол разлёта и длину траектории, выберите источник.",
  "ec.teilchen.flug": "Полёт",
  "ec.teilchen.auftrieb": "Подъёмная сила",
  "ec.teilchen.schnuppe.auftrieb": "Здесь подъёмная сила наклоняет путь: −1 — круто вниз, 0 — горизонтально, +1 — вверх. Темп ускоряет звезду, ветер наклоняет её, затухание задаёт длительность свечения хвоста.",
  "ec.teilchen.schar.auftrieb": "Здесь подъёмная сила задаёт высоту стаи. Темп — скорость и взмахи крыльев, ветер наклоняет путь вбок.",
  "ec.teilchen.schnuppe.still": "Для падающих звёзд настройки «Напор», «Направление», «Угол разлёта» и «Длина» не действуют: звезда движется по собственной прямой траектории.",
  "ec.teilchen.schar.still": "Для стаи настройки «Напор», «Направление», «Угол разлёта», «Длина» и «Затухание» не действуют: её движение подчиняется собственным правилам.",
  "ec.teilchen.kanone.salven": "Частоту залпов задаёт модуляция справа — по частоте или по ритмической сетке. Без модуляции пушка стреляет раз в 1,6 секунды.",
  "ec.teilchen.vorschau.titel": "Источник и двенадцать миниатюрных траекторий: где частицы появляются, куда летят, где исчезают",
