  "ec.schleife.art.pixel": "Пиксели",
  "ec.schleife.prinzip.keiner": "видео целиком проигрывается за время клипа; в конце воспроизведение скачком возвращается к началу",
  "ec.schleife.prinzip.ruecklauf": "видео идёт вперёд, а во время перехода быстро перематывается к началу с размытием 8 %",
  "ec.schleife.prinzip.pendel": "вперёд-назад по фрагменту с исходной скоростью воспроизведения и плавными разворотами; переход не нужен",
  "ec.schleife.prinzip.abbremsen": "видео останавливается и наплывом переходит в первый кадр",
  "ec.schleife.prinzip.unschaerfe": "в середине перехода размытие скрывает склейку конца видео с началом",
  "ec.schleife.prinzip.blende": "последний кадр плавно переходит в первый",
  "ec.schleife.prinzip.kreuzzoom": "в середине перехода зум с размытием скрывает склейку конца видео с началом",
  "ec.schleife.prinzip.wisch": "начало выталкивает конец влево",
  "ec.schleife.prinzip.schwarz": "затемнение до чёрного, переход от конца видео к началу, выход из чёрного",
  "ec.schleife.prinzip.weiss": "осветление до белого, переход от конца видео к началу, возвращение к обычному изображению",
  "ec.schleife.prinzip.blitz": "жёсткая замена под короткой белой вспышкой; подходит для графики, но выглядит резко в съёмочном видео",
  "ec.schleife.prinzip.pixel": "кадр распадается на блоки, которые скрывают переход от конца видео к началу; для графики",
  "ec.schleife.gruppe.bewegung": "Движение",
