  "ec.zonen.hoechstens": "Максимум границ: {n}. Больше зон уже не различить.",
  "ec.text.ort_vorgabe": "Положение текста сброшено к исходному.",
  "ec.kb.geloest.eins": "Точка удалена. Осталось: {n}.",
  "ec.kb.geloest.mehr": "Точка удалена. Осталось: {n}.",
  "ec.kb.geloest.letzter": "Последняя точка удалена. Камера показывает весь кадр.",
  "ec.brand.anteil": "Пересвет: {p} % изображения",
  "ec.brand.quelle": " (в самом источнике: {p} %)",
  "ec.brand.titel": "Доля пикселей, недавно достигших предела хотя бы в одном канале (максимум за две секунды). Дальнейшее усиление увеличит площадь пересвета, а не яркость.",
  "ec.kb.px_grenze": "Диапазон ползунка ограничен {max} %. Предел рассчитан по 325 картам глубины из библиотеки: для каждой карты измерен максимальный перепад между соседними пикселями, медиана этих значений — {sprung}. При {grenze} % ширина разрыва достигает {sicht} пикс. При такой ширине заполнение разрыва продолжением края изображения уже не даёт надёжного результата.",
  "ec.kb.px_aus": "Выключено: кадр увеличивается равномерно, как при увеличении фотографии. Эффекта движения камеры нет. ",
  "ec.kb.px_satz": "Ближний план смещается относительно дальнего на {s} % длины большей стороны изображения — это {px} пикс. при размере предпросмотра в студии. Разница максимальна там, где кадр сместился дальше всего. К середине движения она уменьшается: смещение расходится от целевой точки. При этой настройке медианная расчётная ширина разрыва на самой резкой границе между планами — {riss} пикс. Примерно для 10 % треков она составляет не менее {riss90} пикс. Расчёт основан на 325 картах глубины при размере предпросмотра в студии и максимальном приближении. Разрыв заполняется изображением из дальнего слоя.",
  "ec.kb.lupe.anderthalb": "в полтора раза",
  "ec.kb.lupe.fach": "в {f} раза",
