  "ec.ablage.eine_anpassung": "1 коррекция",
  "ec.ablage.n_anpassungen": "коррекций: {n}",
  "ec.ablage.kopieren_titel": "Скопировать текущее состояние студии — источник, подготовку, цепь эффектов и цикл — для переноса на другой трек. В буфере хранится один рецепт; он сохраняется при перезагрузке страницы.",
  "ec.ablage.kopieren_leer": "Копировать нечего. Сначала выберите другой источник, настройте подготовку, добавьте эффект или переход.",
  "ec.ablage.einfuegen_aus": "Вставить из «{her}»",
  "ec.ablage.einfuegen": "Вставить",
  "ec.ablage.einfuegen_titel": "Применить запомненный рецепт к треку: цепь эффектов, подготовка и цикл переносятся всегда, источник — только если есть у этого трека. Автоматически ничего не сохраняется; затем нажмите «Сохранить для этого трека».",
  "ec.ablage.gemerkt_am": " Запомнено {wann}.",
