  "ec.ablage.nicht_gesichert": "ещё не сохранено. Нажмите «Сохранить для этого трека». При закрытии и открытии вернётся сохранённый рецепт.",
  "ec.ablage.leer_altes_rezept": "сейчас здесь ничего не задано, но прежний рецепт ещё сохранён у трека. Если закрыть студию и открыть снова, он загрузится. Чтобы удалить его, нажмите «Удалить».",
  "ec.ablage.leer_nichts": "сейчас ничего не задано и у трека ничего не сохранено.",
  "ec.vorb.reg.kurve": "Кривая",
