  "ec.vorb.reg.tiefe": "Глубина",
  "ec.vorb.auto_titel": "Чёрная и белая точки из гистограммы (0.5 % / 99.5 %)",
  "ec.vorb.auto": "Автоуровни",
  "ec.vorb.zuruecksetzen_titel": "Сбросить всю подготовку к нейтральной. Кнопка «Удалить» внизу относится к сохранённому клипу с эффектами.",
  "ec.vorb.zuruecksetzen": "Сбросить",
  "ec.vorb.tonwert": "Тон",
  "ec.vorb.marken": "Перетащите маркеры снизу для чёрной и белой точек",
  "ec.vorb.raum": "Пространство",
  "ec.vorb.raumtiefe": "Глубина пространства",
  "ec.vorb.raumtiefe_satz": "Карта глубины, полученная ИИ, задаёт лишь <i>порядок</i> объектов от ближних к дальним, а не реальные расстояния между ними. Поэтому глубину нужно задать в ширинах изображения: для портрета — примерно 0,2, для пейзажа — 3 и больше. Значение зависит прежде всего от самого изображения.",
  "ec.vorb.zonen": "Зоны",
  "ec.vorb.zonen_satz": "На карте глубины, полученной ИИ из обложки, можно задать зоны действия эффектов с помощью гистограммы у правого края изображения — как планы театральной декорации. Перемещайте предложенные границы, добавляйте новые <b>одним кликом</b> и удаляйте <b>двойным кликом</b>. Для удобства поверните рельеф мышью; двойной клик вернёт исходный вид.",
  "ec.vorb.raumfolge": "Пространство от переднего плана к заднему",
  "ec.vorb.anteil_tiefe": "{p} % глубины",
  "ec.vorb.raumfuss": "Всё это <b>перед объективом</b> и движется с камерой. Зерно и виньетка возникают за ним, на плёнке и в объективе; они закреплены на кадре и не масштабируются.",
  "ec.vorb.keine_karte": "У изображения нет карты глубины, поэтому нет зон.",
  "ec.vorb.eine_zone": "Сейчас задана <b>одна зона</b>: значения глубины образуют один кластер, а на гистограмме нет провала, по которому можно разделить два плана. Границу всё равно можно добавить вручную.",
  "ec.vorb.n_zonen": "Сейчас задано зон: <b>{n}</b>",
  "ec.vorb.zone_name": "глубины изображения — <b>{name}</b>",
  "ec.vorb.max_grenzen": "максимум границ: {n}. Больше планов зритель не различит.",
  "ec.vorb.von_selbst": "автоматически",
