  "ec.rezept.zone_einer": "{was}: настройка была у одного эффекта, теперь действует на всю сцену (Подготовка › Глубина)",
  "ec.rezept.zone_mehrere": "{was}: настройка была у эффектов ({n}), теперь действует на всю сцену (Подготовка › Глубина)",
  "ec.rezept.zone_sorten": ", разных значений: {n}. Выбрано самое частое.",
  "ec.rezept.zone_trennung": "разделение",
  "ec.rezept.zone_weichheit": "мягкость границы",
  "ec.rezept.zone_leerraum": "пустой передний план",
  "ec.rezept.bildzeile_alt_eins": "у одного эффекта была «Глубина по строке изображения». Ползунок удалён, значение больше не действует.",
  "ec.rezept.bildzeile_alt_n": "эффектов с настройкой «Глубина по строке изображения»: {n}. Ползунок удалён, значение больше не действует.",
  "ec.rezept.fahrt_alt_eins": "один эффект — прежнее «Движение». Оно удалено, ту же задачу выполняет Движение Ken Burns.",
  "ec.rezept.fahrt_alt_n": "эффектов «Движение» удалено: {n}. Их заменяет эффект «Движение Ken Burns».",
