  "ec.rezept.zielpunkt_enger_eins": "у одной целевой точки охват меньше, чем допускала прежняя версия рецепта: раньше минимум был 0,50, теперь — 0,25. Центр точки смещается соответственно",
  "ec.rezept.zielpunkt_enger_n": "целевых точек с охватом меньше, чем допускала прежняя версия рецепта: {n}. Раньше минимум был 0,50, теперь — 0,25. Центры точек смещаются соответственно",
