  "ec.takt.keine_laenge": "нет длительности, сохраняющей ритм всей песни. Пульсации видео Suno расходятся с музыкой.",
  "ec.takt.sitzt": "совпадает с ритмом в {p} % песни",
  "ec.sperre.fuss": "Во время экспорта на нижней панели можно только отменить экспорт. После завершения обычные действия снова будут доступны.",
  "ec.sperre.pult": "Во время экспорта источник, подготовка, цепь и цикл зафиксированы: изменение посреди работы попало бы в готовое видео. Нижняя панель тоже заблокирована, кроме кнопки «Отменить». Остальное приложение работает: плеер, альбом и другие виды доступны.",
  "ec.voll.keine_laenge": "В каталоге нет длительности трека. Без неё полное видео недоступно.",
  "ec.voll.kein_kodierer": "В браузере нет покадрового кодировщика WebCodecs. Полную песню можно лишь записать в реальном времени, но временные метки сместятся и изображение потеряет синхронизацию с музыкой. Поэтому экспорт не выполняется.",
