  "ec.stufe.vorb": "Подготовка",
  "ec.stufe.kette": "Цепь эффектов",
  "ec.stufe.loop": "Зацикливание клипа с эффектами",
  "ec.stufe.quelle.erklaer": "Здесь выбираются изображения или видео для клипа с эффектами.",
  "ec.stufe.vorb.erklaer": "Здесь можно улучшить вид источника и данные глубины. <b>Кривая</b> настраивает общую тональную кривую или отдельные каналы. <b>Точная настройка</b> улучшает экспозицию, контраст, света, тени, цвет, резкость и другое. Данные обрабатываются напрямую, изменения видны только в отображении. <b>Глубина</b> задаёт восприятие изображения как пространства; некоторым эффектам нужны зоны действия в нём.",
  "ec.stufe.kette.erklaer1": "Каждый эффект накладывает слой на выбранный источник. Действуют сверху вниз: каждый следующий — поверх результата предыдущих.",
  "ec.stufe.kette.erklaer2": "Пульсации следуют ритму песни.",
  "ec.stufe.kette.erklaer3": "Значок соло показывает эффект отдельно.",
  "ec.stufe.kette.erklaer4": "Эффект и источник вместе образуют клип с эффектами.",
  "ec.stufe.loop.erklaer1": "Suno воспроизводит видео к песне по кругу и допускает не более 10 секунд. Чтобы пульсации сохраняли ритм на протяжении песни, длительность клипа составляет целое число долей. Программа подбирает её так, чтобы клип как можно дольше оставался в ритме с музыкой.",
  "ec.stufe.loop.erklaer2": "В конце клипа изображение должно точно вернуться к началу. Эффекты делают это автоматически, без рывков и швов. Видео подгоняется скоростью; при разных начале и конце добавляется переход.",
  "ec.studio.titel": "Студия клипов с эффектами",
  "ec.studio.spielen_titel": "Запустить трек в плеере — тогда пульсации будут следовать его ритму",
  "ec.studio.spielen": "▶ Включить трек",
  "ec.studio.schliessen_titel": "Закрыть (Esc)",
  "ec.studio.ohne_effekte": "без эффектов",
  "ec.kette.presets_titel": "Готовые настройки — мягкие сочетания для начала",
  "ec.kette.presets": "Готовые настройки…",
  "ec.kette.alle_an_aus": "включить всё / выключить всё",
  "ec.kette.kopf_effekt": "Эффект",
  "ec.kette.kopf_nr_titel": "Номер, если в цепи несколько эффектов одного вида",
  "ec.kette.kopf_nr": "№",
  "ec.kette.alle_weg_titel": "удалить всё — с подтверждением",
