  "ec.loop.lage_titel": "Длительность, которую сейчас выбрал бы «Экспорт 10 с», и доля песни с совпадающим ритмом",
  "ec.loop.ansicht_titel": "Предпросмотр показывает кадр экспортированного клипа, который Suno показывает в тот же момент песни. Включается при открытии этого этапа, выключается при открытии другого.",
  "ec.loop.ansicht": "показать как клип 10 с",
  "ec.loop.schlaege_im_clip": "Долей в клипе",
  "ec.loop.weniger_titel": "меньше долей — короче клип, быстрее видео",
  "ec.loop.mehr_titel": "больше долей — длиннее клип (до 10 с), медленнее воспроизведение видео",
  "ec.loop.selbst_schlaege_titel": "подобрать число долей с лучшей синхронизацией по всей песне",
  "ec.loop.von_selbst": "автоматически",
  "ec.loop.uebergang_enden": "Переход на стыке цикла",
  "ec.loop.kuerzer_titel": "короче, с шагом в полдоли. Длительность клипа не меняется: освободившееся время занимает видео.",
  "ec.loop.laenger_titel": "длиннее, максимум треть клипа",
  "ec.loop.selbst_uebergang_titel": "подобрать переход по ритму: такт, а при длинных тактах — полтакта",
  "ec.loop.yachse_titel": "время исходного видео снизу вверх",
  "ec.loop.yachse_name": "Видео",
  "ec.loop.leiste_titel": "По горизонтали — зацикленная версия KlangTresor, по вертикали — время исходника. Кривая связывает кадр видео со временем клипа, заливка — переход, метки снизу — доли.",
  "ec.loop.xachse_titel": "зацикленная версия KlangTresor слева направо",
  "ec.loop.xachse_name": "зацикленный клип",
  "ec.loop.kosten": "при первом включении видео однократно измеряется несколько секунд; с видео «Экспорт 10 с» занимает дольше",
  "ec.fuss.effektclip": "Клип с эффектами",
  "ec.fuss.sichern_titel": "Сохранить для трека источник, подготовку, цепь эффектов и цикл. Плитка и сцена будут показывать результат в реальном времени, в ритм песни.",
  "ec.fuss.sichern": "Сохранить для этого трека",
  "ec.fuss.ungesichert_titel": "Настройки студии отличаются от сохранённых. «Сохранить для этого трека» запишет их; закрытие и открытие вернёт сохранённый рецепт.",
  "ec.fuss.ungesichert": "ещё не сохранено",
  "ec.fuss.loeschen_titel": "Удалить сохранённый клип с эффектами: источник, подготовку, цепь и цикл. Плитка и сцена снова покажут неподвижное изображение. Удаляется только рецепт: обложка и видео остаются, текущая настройка студии тоже остаётся и может быть сохранена снова.",
  "ec.fuss.loeschen": "Удалить",
  "ec.fuss.kopieren_titel": "Запомнить состояние студии для переноса на другой трек",
  "ec.fuss.kopieren": "Копировать",
  "ec.fuss.einfuegen_titel": "Применить запомненный рецепт к треку без сохранения",
  "ec.fuss.einfuegen": "Вставить",
  "ec.fuss.video_titel": "До десяти секунд MP4 в папку «Загрузки». Длительность подбирается для сохранения ритма всей песни. Без звука, в формате источника, с фирменной меткой.",
  "ec.fuss.video": "Экспорт 10 с",
  "ec.fuss.voll_titel": "Вся песня MP4 в папку «Загрузки»: тот же вид, что в плитке, на полную длину, в формате источника, с фирменной меткой. Студия на это время фиксируется.",
  "ec.voll.ton_titel_kurz": "audio.mp3 трека станет звуковой дорожкой видео",
  "ec.voll.abbrechen_titel": "Отменить экспорт. Незавершённое видео будет удалено из приложения.",
  "ec.voll.abbrechen": "Отменить",
  "ec.fuss.hilfe": "Сохраняются источник, подготовка, цепь эффектов и цикл. Если трек звучит в плеере, пульсации следуют его ритму. Клавиши: <kbd>←</kbd><kbd>→</kbd> — источник · удерживать <kbd>V</kbd> — без эффектов (в Подготовке) · <kbd>Esc</kbd> — закрыть",
  "ec.kette.hinzufuegen": "Добавить эффект…",
