  "ec.rezept.quelle_fehlt": "источник отсутствует, показана обложка",
  "ec.rezept.geladen": "Клип с эффектами трека загружен",
  "ec.rezept.keiner": "у трека ещё нет клипа с эффектами",
  "ec.tiefe.boden_trennt_nicht": "Карта глубины не разделяет планы (диапазон {s} из 255). На ней нет опорной поверхности, от которой могли бы подниматься частицы.",
  "ec.tiefe.boden_ohne_raum": "На карте глубины найдена опорная поверхность (ячеек: {n}), но пространство над ней не входит в выбранную зону. Для появления частиц нет места.",
  "ec.tiefe.boden_keiner": "На этой карте ни в одной точке поверхность не уходит вдаль по направлению к верхнему краю — опорной поверхности не найдено.",
  "ec.titel.abgang_instrumental": "Инструментальный трек: заголовок исчезает через четыре такта.",
  "ec.titel.abgang_bei": "Здесь исчезновение завершается на {t} с, до первой строки.",
  "ec.titel.abgang_ohne_lyrik": "Без очищенного текста исчезает через четыре такта.",
  "ec.titel.auftritt_partikel": "Только в полном треке: заголовок собирается за два такта из частиц выбранного в цепи вида, удерживается и за два такта распадается по ветру. Вид, цвет, размер, ветер и гравитация — из эффекта Частицы. {hier}",
  "ec.titel.auftritt": "Только в полном треке: доля на вход, удержание, исчезновение за долю до первой спетой строки (не ранее двух тактов). Вход с плавным торможением, выход с плавным разгоном; регулятора нет. {hier}",
  "ec.titel.zehnsekuender": "В десятисекундном клипе заголовок неподвижен. Появление и исчезновение только в полном треке.",
  "ec.titel.partikel_fehlt": "Для «Из частиц» нужен эффект Частицы: пепел, пыль, искры, блёстки, снег, семена одуванчика или светлячки. Пока заголовок неподвижен.",
  "ec.titel.hochformat": "Вертикальный формат: элементы управления Reels, TikTok и Shorts занимают примерно нижнюю пятую часть изображения. При значении «Позиция Y» до 0,78 текст остаётся выше этой области.",
  "ec.titel.im_karaoke_band": "Заголовок попадает на подложку караоке. Измените «Позиция Y», чтобы поднять заголовок над ней (ориентир — 0,12).",
  "ec.lyrik.deckung_gering": "Whisper распознал лишь {p} % слов — мало для надёжной синхронизации",
  "ec.lyrik.japanisch": "Текст японским письмом: Whisper даёт транслитерацию, сопоставление невозможно",
  "ec.lyrik.zurueckgestellt": "очищенный текст отложен",
  "ec.lyrik.nie_gerechnet": "очищенный текст ещё не подготовлен. Он создаётся при утреннем обновлении на этапе «Временные метки караоке с Whisper». Нужен настроенный Whisper, см. START-HIER.md. У чужих треков его нет.",
  "ec.lyrik.laden_fehler": "не удалось загрузить очищенный текст. Повтор через 30 с.",
  "ec.lyrik.kein_gesang": "<b>Нет строки для отображения</b>: у трека нет вокала.",
